/* eslint-disable */

/**
 * Particles that gather into a shape ("home" points), drift with a soft noise,
 * flee the pointer and scatter when `scatter` goes from 0 to 1.
 */
export class Dust {
    free(): void;
    [Symbol.dispose](): void;
    count(): number;
    constructor(count: number, width: number, height: number, seed: number);
    /**
     * Pointer to `count() * 2` interleaved f32 positions inside `memory()`.
     */
    positions(): number;
    resize(width: number, height: number): void;
    /**
     * Interleaved x, y target points; reused cyclically if there are fewer points than particles.
     */
    set_home(points: Float32Array): void;
    /**
     * Advances the simulation by `dt` seconds. `(px, py)` is the pointer (NaN when absent).
     */
    step(dt: number, px: number, py: number, scatter: number): void;
}

/**
 * Head tags for the playground, generated by the `active` crate.
 */
export function seo_head(title: string, description: string, path: string, origin: string): string;

/**
 * The WebAssembly memory, so JavaScript can read particle positions without copying.
 */
export function wasm_memory(): any;

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
    readonly memory: WebAssembly.Memory;
    readonly __wbg_dust_free: (a: number, b: number) => void;
    readonly dust_count: (a: number) => number;
    readonly dust_new: (a: number, b: number, c: number, d: number) => number;
    readonly dust_positions: (a: number) => number;
    readonly dust_resize: (a: number, b: number, c: number) => void;
    readonly dust_set_home: (a: number, b: number, c: number) => void;
    readonly dust_step: (a: number, b: number, c: number, d: number, e: number) => void;
    readonly seo_head: (a: number, b: number, c: number, d: number, e: number, f: number, g: number, h: number, i: number) => void;
    readonly wasm_memory: () => number;
    readonly __wbindgen_export: (a: number, b: number) => number;
    readonly __wbindgen_add_to_stack_pointer: (a: number) => number;
    readonly __wbindgen_export2: (a: number, b: number, c: number, d: number) => number;
    readonly __wbindgen_export3: (a: number, b: number, c: number) => void;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;

/**
 * Instantiates the given `module`, which can either be bytes or
 * a precompiled `WebAssembly.Module`.
 *
 * @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
 *
 * @returns {InitOutput}
 */
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
 * If `module_or_path` is {RequestInfo} or {URL}, makes a request and
 * for everything else, calls `WebAssembly.instantiate` directly.
 *
 * @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
 *
 * @returns {Promise<InitOutput>}
 */
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
